export const RIG={shoulderX:.2125,shoulderY:1.25,upper:.275,lower:.295,restZ:.15};export function calibrate({shoulderX:t,shoulderY:o,upper:s,lower:n,restZ:c}={}){return t>0&&(RIG.shoulderX=t),o>0&&(RIG.shoulderY=o),s>0&&(RIG.upper=s),n>0&&(RIG.lower=n),typeof c=="number"&&(RIG.restZ=c),{...RIG}}export const reach=()=>RIG.upper+RIG.lower-.001,fold=()=>Math.abs(RIG.upper-RIG.lower)+.01;const l=t=>{let o=t;for(;o>Math.PI;)o-=Math.PI*2;for(;o<-Math.PI;)o+=Math.PI*2;return o},i=(t,o,s)=>t<o?o:t>s?s:t;function f(t,o,s){const n=t.x-o*RIG.shoulderX,c=t.y-RIG.shoulderY,r=t.z,e=Math.hypot(n,c,r)||1e-6,a=i(e,fold(),reach()),h=(RIG.upper*RIG.upper+RIG.lower*RIG.lower-a*a)/(2*RIG.upper*RIG.lower),p=-(Math.PI-Math.acos(i(h,-1,1))),x=-RIG.upper-RIG.lower*Math.cos(p),w=-RIG.lower*Math.sin(p),M=a/e,d=n*M,y=c*M,b=r*M;let u=Math.asin(i(-d/x,-1,1));s&&(u=Math.PI-u);const z=x*Math.cos(u),I=Math.atan2(b,y)-Math.atan2(w,z);return{armX:l(I),armZ:l(u),foreX:p}}export function solveArm(t,o=1){const s=o*RIG.restZ,n=f(t,o,!1),c=f(t,o,!0),r=e=>Math.abs(l(e.armZ-s));return r(c)<r(n)?c:n}export function handAt(t,o,s,n=1){const c=-RIG.upper-RIG.lower*Math.cos(s),r=-RIG.lower*Math.sin(s),e=c*Math.cos(o);return{x:n*RIG.shoulderX-c*Math.sin(o),y:RIG.shoulderY+e*Math.cos(t)-r*Math.sin(t),z:e*Math.sin(t)+r*Math.cos(t)}}export function toRigSpace(t,o,s,n){const c=(t.x-o.x)/n,r=(t.y-(o.y||0))/n,e=(t.z-o.z)/n,a=Math.cos(-s),h=Math.sin(-s);return{x:c*a+e*h,y:r,z:-c*h+e*a}}
